import java.util.ArrayList;
import java.util.List;

List<String> spells = new ArrayList<>();
spells.add("Fireball");
spells.add("Heal");
spells.add("Ice Lance");
System.out.println(spells.get(1)); // Heal
System.out.println(spells.size()); // 3

import java.util.Collections;

for (String s : spells) {
    System.out.println(s);
}

Collections.sort(spells); // alphabetical

